import hashlib
import hmac
import os
import json
import unicodedata
import time
import secrets
from typing import Optional, Dict, Any


class UserStore:
    """Secure user storage with normalized username lookups."""

    def __init__(self):
        self._users: Dict[str, Dict[str, Any]] = {}
        self._salt_rounds = 100000

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, self._salt_rounds)

    def _normalize_username(self, username: str) -> str:
        """Normalize username to prevent homoglyph attacks.
        Uses NFC normalization for canonical equivalence."""
        # Strip leading/trailing whitespace
        username = username.strip()
        # Apply Unicode NFC normalization
        normalized = unicodedata.normalize('NFC', username)
        # Case fold for case-insensitive comparison
        return normalized.casefold()

    def register(self, username: str, password: str, role: str = 'user') -> bool:
        """Register a new user with normalized username."""
        if not username or not password:
            return False
        if len(username) > 64 or len(password) > 128:
            return False

        norm_name = self._normalize_username(username)
        if norm_name in self._users:
            return False

        salt = os.urandom(32)
        pw_hash = self._hash_password(password, salt)

        self._users[norm_name] = {
            'username_display': username,
            'password_hash': pw_hash,
            'salt': salt,
            'role': role,
            'created_at': time.time()
        }
        return True

    def authenticate(self, username: str, password: str) -> Optional[Dict[str, Any]]:
        """Authenticate user and return user info if valid."""
        norm_name = self._normalize_username(username)
        user = self._users.get(norm_name)
        if user is None:
            # Constant-time-ish: still hash to prevent timing oracle
            self._hash_password(password, os.urandom(32))
            return None

        pw_hash = self._hash_password(password, user['salt'])
        if not hmac.compare_digest(pw_hash, user['password_hash']):
            return None

        return {'username': norm_name, 'role': user['role']}


class TokenService:
    """JWT-like token service for session management."""

    def __init__(self):
        self._signing_key = os.urandom(32)
        self._tokens: Dict[str, float] = {}  # token_id -> expiry
        self._token_lifetime = 3600

    def issue(self, user_info: Dict[str, Any]) -> str:
        token_id = secrets.token_hex(16)
        expiry = time.time() + self._token_lifetime
        payload = {
            'sub': user_info['username'],
            'role': user_info['role'],
            'jti': token_id,
            'exp': expiry
        }
        payload_bytes = json.dumps(payload, separators=(',', ':')).encode('utf-8')
        sig = hmac.new(self._signing_key, payload_bytes, 'sha256').digest()
        import base64
        token = base64.urlsafe_b64encode(payload_bytes + b'.' + sig).decode('ascii')
        self._tokens[token_id] = expiry
        return token

    def verify(self, token: str) -> Optional[Dict[str, Any]]:
        import base64
        try:
            raw = base64.urlsafe_b64decode(token.encode('ascii'))
        except Exception:
            return None

        parts = raw.rsplit(b'.', 1)
        if len(parts) != 2:
            return None

        payload_bytes, sig = parts
        expected_sig = hmac.new(self._signing_key, payload_bytes, 'sha256').digest()
        if not hmac.compare_digest(sig, expected_sig):
            return None

        payload = json.loads(payload_bytes)
        if payload.get('jti') not in self._tokens:
            return None
        if time.time() > payload.get('exp', 0):
            del self._tokens[payload['jti']]
            return None

        return payload


class AccessControl:
    """Role-based access control with admin impersonation."""

    ROLE_HIERARCHY = {'superadmin': 100, 'admin': 80, 'moderator': 50, 'user': 10}

    def __init__(self, user_store: UserStore, token_service: TokenService):
        self._store = user_store
        self._tokens = token_service

    def login(self, username: str, password: str) -> Optional[str]:
        user_info = self._store.authenticate(username, password)
        if user_info is None:
            return None
        return self._tokens.issue(user_info)

    def check_access(self, token: str, required_role: str) -> bool:
        payload = self._tokens.verify(token)
        if payload is None:
            return False
        user_level = self.ROLE_HIERARCHY.get(payload.get('role', ''), 0)
        required_level = self.ROLE_HIERARCHY.get(required_role, 100)
        return user_level >= required_level

    def admin_impersonate(self, admin_token: str, target_username: str) -> Optional[str]:
        """Allow admin to impersonate another user for support purposes."""
        payload = self._tokens.verify(admin_token)
        if payload is None:
            return None
        if self.ROLE_HIERARCHY.get(payload.get('role', ''), 0) < 80:
            return None

        # Look up target user
        norm_target = self._store._normalize_username(target_username)
        target_user = self._store._users.get(norm_target)
        if target_user is None:
            return None

        # Issue token as target user
        return self._tokens.issue({
            'username': norm_target,
            'role': target_user['role']
        })
